function bestLookoutPair(values: number[]): number {
  let best = -Infinity;
  for (let i = 0; i < values.length; i++) {
    for (let j = i + 1; j < values.length; j++) {
      best = Math.max(best, values[i] + values[j] - (j - i));
    }
  }
  return best;
}

